  function esc(s){
    if(!s)return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function sendToChat(txt){
    setTimeout(function(){
      try{
        var w=window.parent||window;
        var ta=w.document.getElementById('send_textarea')||
               w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
        if(ta){
          var d=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
          if(d&&d.set)d.set.call(ta,txt);else ta.value=txt;
          ta.dispatchEvent(new Event('input',{bubbles:true}));
          setTimeout(function(){
            try{
              var sb=w.document.getElementById('send_but');
              if(sb)sb.click();
              else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));
            }catch(e){}
          },150);
          return;
        }
      }catch(e){}
      try{navigator.clipboard.writeText(txt);}catch(e){}
    },450);
  }

  function renderStat(){
    var d=S.data;
    var ln=S.lang==='th'?1:0;
    var col=d.theme_color||REGION_COLOR[d.region]||'#C89B3C';
    applyTheme(col);

    // header sigil
    document.getElementById('hdr-sigil').innerHTML=sigil(d.region,col).replace(/<svg[^>]*>/,'').replace(/<\/svg>/,'');
    document.getElementById('hdr-name').textContent=d.name||'—';
    document.getElementById('hdr-title').textContent='STATUS TRACKER';

    // tab labels
    document.getElementById('t0').textContent=t('stat');
    document.getElementById('t1').textContent=t('skill');
    document.getElementById('t2').textContent=t('items');
    document.getElementById('t3').textContent=t('gear');
    document.getElementById('t4').textContent=t('craft');
    document.getElementById('t5').textContent=t('log');

    // section labels
    document.getElementById('sec-vital').textContent=t('vital');
    document.getElementById('sec-cond').textContent=t('cond');
    document.getElementById('sec-skills').textContent=t('skills');
    document.getElementById('sec-items').textContent=t('inv');
    document.getElementById('sec-gear').textContent=t('eq');
    document.getElementById('sec-craft').textContent=t('cr');
    document.getElementById('sec-log').textContent=t('lg');
    document.getElementById('lbl-ingredients').textContent=t('ingredients');
    document.getElementById('lbl-selected').textContent=t('selected');
    document.getElementById('craft-intent').placeholder=t('intent_ph');
    document.getElementById('btn-craft').textContent=t('craft_btn');
    document.getElementById('footer').textContent=t('footer');

    // info grid
    var rows=[
      [t('name'),d.name||'—'],
      [t('age'),d.age||'—'],
      [t('gender'),d.gender||'—'],
      [t('region'),d.region||'—'],
      [t('bg'),d.background||'—'],
      [t('goal'),d.goal||'—']
    ];
    var gh=document.getElementById('info-grid');
    gh.innerHTML='';
    rows.forEach(function(r,i){
      var cls='icard'+(i>=4?' full':'');
      gh.innerHTML+='<div class="'+cls+'"><div class="icard-l">'+esc(r[0])+'</div><div class="icard-v">'+esc(r[1])+'</div></div>';
    });

    // bars
    var hp=d.hp||{cur:0,max:100};var mp=d.mana||{cur:0,max:100};
    var bh=document.getElementById('bars');
    bh.innerHTML='<div class="bar-row"><div class="bar-label">'+t('hp')+'</div><div class="bar-track"><div class="bar-fill bar-hp" id="bar-hp" data-pct="'+Math.min(100,Math.round(hp.cur/Math.max(1,hp.max)*100))+'"></div></div><div class="bar-val">'+hp.cur+'/'+hp.max+'</div></div>'+
    '<div class="bar-row"><div class="bar-label">'+t('mp')+'</div><div class="bar-track"><div class="bar-fill bar-mp" id="bar-mp" data-pct="'+Math.min(100,Math.round(mp.cur/Math.max(1,mp.max)*100))+'"></div></div><div class="bar-val">'+mp.cur+'/'+mp.max+'</div></div>';
    setTimeout(function(){
      ['bar-hp','bar-mp'].forEach(function(id){
        var el=document.getElementById(id);
        if(el)el.style.width=el.getAttribute('data-pct')+'%';
      });
    },100);

    // conditions
    var conds=d.conditions||[];var injs=d.injuries||[];
    var cb=document.getElementById('conditions');
    cb.innerHTML='';
    if(!conds.length&&!injs.length){
      cb.innerHTML='<span class="badge empty">'+esc(S.lang==='th'?'ปกติ':'Normal')+'</span>';
    } else {
      conds.forEach(function(c){cb.innerHTML+='<span class="badge condition">'+esc(c)+'</span>';});
      injs.forEach(function(c){cb.innerHTML+='<span class="badge injury">⚠ '+esc(c)+'</span>';});
    }
  }

  function renderSkills(){
    var d=S.data;var ab=d.abilities||[];
    var el=document.getElementById('abilities-list');
    if(!ab.length){el.innerHTML='<div class="empty-state">'+t('no_ability')+'</div>';return;}
    el.innerHTML=ab.map(function(a){
      var rk=a.rank||'D';
      return '<div class="ability-card"><div class="rank-badge rank-'+rk+'">'+esc(rk)+'</div>'+
        '<div class="ability-info"><div class="ab-name">'+esc(a.name)+'</div><div class="ab-desc">'+esc(a.desc)+'</div></div></div>';
    }).join('');
  }

  function renderInventory(){
    var d=S.data;var inv=d.inventory||[];
    var el=document.getElementById('inventory-list');
    if(!inv.length){el.innerHTML='<div class="empty-state">'+t('no_inv')+'</div>';return;}
    var groups={};
    inv.forEach(function(item){var tp=item.type||'Other';if(!groups[tp])groups[tp]=[];groups[tp].push(item);});
    var html='';
    Object.keys(groups).forEach(function(tp){
      html+='<div class="inv-group"><div class="inv-type-label">'+esc(tp)+'</div>';
      groups[tp].forEach(function(item){
        html+='<div class="inv-item"><div class="inv-qty">×'+esc(item.qty||1)+'</div>'+
          '<div><div class="inv-name">'+esc(item.name)+'</div>'+(item.desc?'<div class="inv-desc">'+esc(item.desc)+'</div>':'')+'</div></div>';
      });
      html+='</div>';
    });
    el.innerHTML=html;
  }

  function renderGear(){
    var d=S.data;var eq=d.equipment||[];
    var SLOTS=['Main Hand','Off Hand','Armor','Head','Feet','Accessory'];
    var el=document.getElementById('gear-list');
    if(!eq.length){el.innerHTML='<div class="empty-state">'+t('no_gear')+'</div>';return;}
    var slotMap={};eq.forEach(function(e){slotMap[e.slot]=e;});
    el.innerHTML=SLOTS.map(function(slot){
      var e=slotMap[slot];
      var cc=e?'<span class="eq-cond cond-'+(e.condition||'good')+'">'+esc(e.condition||'good')+'</span>':'';
      var content=e?
        '<div class="eq-name">'+esc(e.name)+cc+'</div>'+(e.desc?'<div class="eq-desc">'+esc(e.desc)+'</div>':''):
        '<div class="eq-empty">—</div>';
      return '<div class="eq-slot"><div class="eq-slot-label">'+esc(slot)+'</div><div class="eq-slot-line"></div><div class="eq-item">'+content+'</div></div>';
    }).join('');
  }

  function renderCraft(){
    var inv=S.data.inventory||[];
    var el=document.getElementById('craft-pills');
    if(!inv.length){el.innerHTML='<span class="badge empty">'+t('no_inv_craft')+'</span>';return;}
    el.innerHTML=inv.map(function(item,i){
      var sel=S.craftSel.indexOf(i)>=0?' selected':'';
      return '<div class="craft-pill'+sel+'" onclick="W.toggleCraft('+i+')" data-idx="'+i+'">'+
        esc(item.name)+' <span class="qty">×'+esc(item.qty||1)+'</span></div>';
    }).join('');
    renderCraftSelected();
  }

  function renderCraftSelected(){
    var inv=S.data.inventory||[];
    var el=document.getElementById('craft-selected-display');
    if(!S.craftSel.length){el.textContent=t('sel_none');el.classList.remove('has-items');return;}
    el.classList.add('has-items');
    el.textContent=S.craftSel.map(function(i){
      var item=inv[i];return item?item.name+' ×'+(item.qty||1):'?';
    }).join(' + ');
  }

  function renderRecipes(){
    var d=S.data;var rc=d.recipes||[];
    var el=document.getElementById('recipes-list');
    if(!rc.length){el.innerHTML='<div class="empty-state">'+t('no_recipe')+'</div>';return;}
    el.innerHTML=rc.map(function(r){
      var qc='q-'+(r.quality||'ok');
      return '<div class="recipe-card">'+
        '<div class="recipe-header">'+
          '<div class="recipe-name">'+esc(r.name)+'</div>'+
          '<span class="recipe-quality '+qc+'">'+esc(r.quality||'ok')+'</span>'+
          '<button class="btn-del" onclick="W.deleteRecipe('+r.id+',\''+esc(r.name)+'\')">'+t('del')+'</button>'+
        '</div>'+
        '<div class="recipe-ingredients">'+t('ingredients_lbl')+' '+esc((r.ingredients||[]).join(', '))+'</div>'+
