  function renderAll(){
    renderStat();renderSkills();renderInventory();renderGear();renderCraft();renderRecipes();
  }

  function init(){
    var raw=document.getElementById('raw');
    if(raw&&raw.value&&raw.value.trim()&&raw.value.trim()!=='$1'){
      try{
        var txt=raw.value.trim();
        S.data=JSON.parse(txt);
        if(S.data.lang)S.lang=S.data.lang;
      }catch(e){S.data={};}
    }
    renderAll();
  }

  return {
    toggle:function(){document.getElementById('win').classList.toggle('closed');},
    toggleLang:function(){
      S.lang=S.lang==='en'?'th':'en';
      document.getElementById('lnBtn').textContent=S.lang==='en'?'EN':'TH';
      renderAll();
    },
    tab:function(n){
      document.querySelectorAll('.tab').forEach(function(t,i){t.classList.toggle('active',i===n);});
      document.querySelectorAll('.panel').forEach(function(p,i){p.classList.toggle('active',i===n);});
    },
    toggleCraft:function(idx){
      var pos=S.craftSel.indexOf(idx);
      if(pos>=0)S.craftSel.splice(pos,1);else S.craftSel.push(idx);
      renderCraft();
    },
    doCraft:function(){
      var inv=S.data.inventory||[];
      if(!S.craftSel.length){alert(S.lang==='th'?'เลือกวัตถุดิบก่อน':'Select ingredients first.');return;}
      var intent=document.getElementById('craft-intent').value.trim();
      if(!intent){alert(S.lang==='th'?'ระบุสิ่งที่ต้องการคราฟ':'Describe what you want to craft.');return;}
      var ingr=S.craftSel.map(function(i){var it=inv[i];return it?it.name+' ×'+(it.qty||1):'?';});
      var payload=JSON.stringify({ingredients:ingr,intent:intent});
      sendToChat('<'+'LOL_CRAFT>'+payload+'<'+'/LOL_CRAFT>');
      S.craftSel=[];
      document.getElementById('craft-intent').value='';
      renderCraft();
    },
    deleteRecipe:function(rid,rname){
      var payload=JSON.stringify({recipe_id:rid,recipe_name:rname});
      sendToChat('<'+'LOL_RECIPE_DELETE>'+payload+'<'+'/LOL_RECIPE_DELETE>');
    },
    init:init
  };
})();

